PageController = class("PageController", Controller)

function PageController:LoadView(callback)
    PageController.super.LoadView(self, function()
        self.view.uiPage.luaOnPreShow = function(action) self:OnBasePreShow(action) end;
        self.view.uiPage.luaOnShowed = function(action) self:OnBaseShowed(action) end;
        if callback ~= nil then
            callback();
        end
    end);
end

---hideCurrentPage:是否隐藏当前页面，默认隐藏(nil) true隐藏 false不隐藏
function PageController:Present(hideCurrentPage)
    if (hideCurrentPage == nil) then
        hideCurrentPage = true;
    end

    local ret = uiSystem.Instance:PresentPageX(self.view.name, hideCurrentPage, function()
        self:OnPageShow();
        CtrlManager.SetActiveController(self);
    end);
end

function PageController:Dismiss()
    if uiSystem.IsPageInStack(self.view.name) then
        uiSystem.DismissPage();
    end
end

---页面显示前的回调
function PageController:OnBasePreShow(action)
    self:OnPreShow();
    if action ~= nil then
        action:DynamicInvoke();
    end
end

---页面显示后的回调
function PageController:OnBaseShowed(action)
    self:OnShowed();
    if action ~= nil then
        action:DynamicInvoke();
    end
end

---页面显示前的回调 方便子类重写
function PageController:OnPreShow()
    if (self.view ~= nil) then
        self.view:OnPreShow(self);
        self.view:OnShow(self);
    end
end

---页面显示后的回调 方便子类重写
function PageController:OnShowed()
    if (self.view ~= nil) then
        self.view:OnShowed(self);
    end
end

function PageController:IsShowing()
    if (self.view ~= nil and self.view.uiPage ~= nil) then
        return self.view.uiPage:IsShowing();
    else
        return false;
    end
end
